import torch
import torch.distributed as dist
import torch.nn as nn
import torch.nn.functional as F


def _world_size():
    if dist.is_available() and dist.is_initialized():
        return dist.get_world_size()
    return 1


def _rank():
    if dist.is_available() and dist.is_initialized():
        return dist.get_rank()
    return 0


def _all_reduce(x):
    if _world_size() == 1:
        return x
    x = x.contiguous()
    dist.all_reduce(x, op=dist.ReduceOp.SUM)
    return x


def _split_last(x):
    ws = _world_size()
    if ws == 1:
        return x
    return torch.chunk(x, ws, dim=-1)[_rank()].contiguous()


def _gather_last(x):
    ws = _world_size()
    if ws == 1:
        return x
    x = x.contiguous()
    parts = [torch.empty_like(x) for _ in range(ws)]
    dist.all_gather(parts, x)
    return torch.cat(parts, dim=-1).contiguous()


class _CopyToParallelRegion(torch.autograd.Function):
    """Identity in forward, all-reduce in backward."""

    @staticmethod
    def forward(ctx, x):
        return x

    @staticmethod
    def backward(ctx, grad):
        return _all_reduce(grad.clone())


class _ReduceFromParallelRegion(torch.autograd.Function):
    """All-reduce in forward, identity in backward."""

    @staticmethod
    def forward(ctx, x):
        return _all_reduce(x.clone())

    @staticmethod
    def backward(ctx, grad):
        return grad


class _ScatterToParallelRegion(torch.autograd.Function):
    """Split last dim in forward, all-gather in backward."""

    @staticmethod
    def forward(ctx, x):
        return _split_last(x)

    @staticmethod
    def backward(ctx, grad):
        return _gather_last(grad)


class _GatherFromParallelRegion(torch.autograd.Function):
    """All-gather along last dim in forward, split in backward."""

    @staticmethod
    def forward(ctx, x):
        return _gather_last(x)

    @staticmethod
    def backward(ctx, grad):
        return _split_last(grad)


class ColumnParallelLinear(nn.Module):
    """Y = X A^T + b with A split along the output dimension.

    Each rank holds weight of shape (out_features // world_size, in_features).
    Output is gathered along the last dimension.
    """

    def __init__(self, in_features, out_features, bias, master_weight):
        super().__init__()
        ws = _world_size()
        rank = _rank()
        assert out_features % ws == 0, "out_features must be divisible by world_size"
        self.in_features = in_features
        self.out_features = out_features
        self.world_size = ws
        self.rank = rank
        self.output_size_per_partition = out_features // ws

        master_weight = master_weight.detach()
        assert tuple(master_weight.shape) == (out_features, in_features)
        n = self.output_size_per_partition
        shard = master_weight[rank * n:(rank + 1) * n, :].clone().contiguous()
        self.weight = nn.Parameter(shard)

        if bias:
            self.bias = nn.Parameter(
                torch.zeros(n, dtype=master_weight.dtype, device=master_weight.device)
            )
        else:
            self.register_parameter("bias", None)

    def forward(self, x):
        x = _CopyToParallelRegion.apply(x)
        out = F.linear(x, self.weight, self.bias)
        return _GatherFromParallelRegion.apply(out)


class RowParallelLinear(nn.Module):
    """Y = X A^T + b with A split along the input dimension.

    Each rank holds weight of shape (out_features, in_features // world_size).
    Partial outputs are summed (all-reduce); bias is full on every rank and
    added after the reduction.
    """

    def __init__(self, in_features, out_features, bias, master_weight):
        super().__init__()
        ws = _world_size()
        rank = _rank()
        assert in_features % ws == 0, "in_features must be divisible by world_size"
        self.in_features = in_features
        self.out_features = out_features
        self.world_size = ws
        self.rank = rank
        self.input_size_per_partition = in_features // ws

        master_weight = master_weight.detach()
        assert tuple(master_weight.shape) == (out_features, in_features)
        n = self.input_size_per_partition
        shard = master_weight[:, rank * n:(rank + 1) * n].clone().contiguous()
        self.weight = nn.Parameter(shard)

        if bias:
            self.bias = nn.Parameter(
                torch.zeros(
                    out_features, dtype=master_weight.dtype, device=master_weight.device
                )
            )
        else:
            self.register_parameter("bias", None)

    def forward(self, x):
        # Accept either the full input (split here) or an already-partitioned input.
        if self.world_size > 1 and x.shape[-1] == self.in_features:
            x = _ScatterToParallelRegion.apply(x)
        partial = F.linear(x, self.weight)
        out = _ReduceFromParallelRegion.apply(partial)
        if self.bias is not None:
            out = out + self.bias
        return out
